import { redirect } from "next/navigation";
import Link from "next/link";
import { currentUser } from "@/lib/auth";
import { listOrdersForCustomer } from "@/lib/orders";
import { EmptyState } from "@/app/components/EmptyState";
import { formatCents, formatDateTime, STATUS_LABELS } from "@/lib/format";

export default async function AccountOrdersPage() {
  const user = await currentUser();
  if (!user) redirect("/signin");

  const orders = await listOrdersForCustomer(user.id);

  return (
    <main className="mx-auto max-w-2xl px-4 py-10 sm:px-6">
      <h1 className="font-display text-3xl font-semibold tracking-tight text-text">Your orders</h1>

      {orders.length === 0 ? (
        <div className="mt-8">
          <EmptyState title="No orders yet" hint="Once you place an order, it'll show up here." />
        </div>
      ) : (
        <div className="mt-8 flex flex-col gap-3">
          {orders.map((order) => (
            <Link
              key={order.id}
              href={`/orders/${order.id}`}
              className="flex items-center justify-between gap-4 rounded-xl border border-border bg-surface p-4 shadow-sm hover:bg-surface2/60"
            >
              <div className="min-w-0">
                <p className="font-medium text-text">Order #{order.id}</p>
                <p className="truncate text-sm text-textMuted">{formatDateTime(order.fulfillment_at)}</p>
              </div>
              <div className="flex flex-shrink-0 flex-col items-end gap-1">
                <span className="rounded-full bg-surface2 px-2.5 py-0.5 text-xs font-medium text-textMuted">
                  {STATUS_LABELS[order.status] ?? order.status}
                </span>
                <span className="font-semibold text-text">{formatCents(order.total_cents)}</span>
              </div>
            </Link>
          ))}
        </div>
      )}
    </main>
  );
}

"use server";

import { revalidatePath } from "next/cache";
import { requireAdminAction } from "@/lib/auth";
import { query } from "@/lib/db";
import { updateOrderStatus, type OrderStatus } from "@/lib/orders";

function slugify(name: string): string {
  return (
    name
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "") || `cake-${Date.now()}`
  );
}

export async function addCakeAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const name = String(formData.get("name") ?? "").trim().slice(0, 200);
  const description = String(formData.get("description") ?? "").trim().slice(0, 2000);
  const priceDollars = Number(formData.get("price") ?? 0);
  const occasion = String(formData.get("occasion") ?? "custom").trim().slice(0, 40);
  if (!name || !Number.isFinite(priceDollars) || priceDollars <= 0) return;

  await query(
    `INSERT INTO cakes (slug, name, description, base_price_cents, occasion_tags, is_sample)
     VALUES ($1, $2, $3, $4, ARRAY[$5]::text[], false)`,
    [slugify(name), name, description, Math.round(priceDollars * 100), occasion],
  );
  revalidatePath("/admin");
  revalidatePath("/shop");
  revalidatePath("/");
}

export async function toggleCakeActiveAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const cakeId = Number(formData.get("cakeId"));
  if (!Number.isInteger(cakeId)) return;
  await query("UPDATE cakes SET active = NOT active WHERE id = $1", [cakeId]);
  revalidatePath("/admin");
  revalidatePath("/shop");
  revalidatePath("/");
}

export async function updateOrderStatusAction(formData: FormData): Promise<void> {
  await requireAdminAction();
  const orderId = Number(formData.get("orderId"));
  const status = String(formData.get("status") ?? "") as OrderStatus;
  const validStatuses: OrderStatus[] = [
    "pending",
    "paid",
    "in_kitchen",
    "ready",
    "out_for_delivery",
    "completed",
    "cancelled",
  ];
  if (!Number.isInteger(orderId) || !validStatuses.includes(status)) return;
  await updateOrderStatus(orderId, status);
  revalidatePath("/admin");
}

export async function removeSampleDataAction(): Promise<void> {
  await requireAdminAction();
  try {
    // Hard-delete the sample rows — the common case, no orders reference them yet.
    await query("DELETE FROM cake_options WHERE cake_id IN (SELECT id FROM cakes WHERE is_sample = true)");
    await query("DELETE FROM cakes WHERE is_sample = true");
  } catch (e) {
    // A sample cake was ordered before cleanup (order_items FK). Never break an
    // existing order's data — fall back to hiding the sample cakes instead.
    console.warn("[admin] sample delete blocked by references, hiding instead", (e as { code?: string })?.code);
    await query("UPDATE cakes SET active = false WHERE is_sample = true");
  }
  revalidatePath("/admin");
  revalidatePath("/shop");
  revalidatePath("/");
}

import { NextResponse } from "next/server";
import { query } from "@/lib/db";
import { createSession } from "@/lib/session";
import {
  LIMITS,
  LOGIN_PAGE,
  clientIp,
  forbidden,
  isCrossSiteRequest,
  landingAfterAuth,
  readCredentials,
  redirectWithError,
  redirectWithSession,
  tooManyAttempts,
  verifyPassword,
} from "@/lib/auth";

export async function POST(req: Request): Promise<NextResponse> {
  if (isCrossSiteRequest(req)) return forbidden();
  const { email, password, invite } = await readCredentials(req);
  const throttled = tooManyAttempts([
    { key: `login:ip:${clientIp(req)}`, limit: LIMITS.ip },
    { key: `login:email:${email}`, limit: LIMITS.email },
  ]);
  if (throttled) return redirectWithError(LOGIN_PAGE, "too_many", invite);
  if (!email || !password) return redirectWithError(LOGIN_PAGE, "invalid", invite);
  let id: number;
  try {
    const found = await query<{ id: number; password_hash: string }>(
      "SELECT id, password_hash FROM users WHERE email = $1",
      [email],
    );
    const row = found.rows[0];
    const ok = await verifyPassword(password, row?.password_hash ?? null);
    if (!row || !ok) return redirectWithError(LOGIN_PAGE, "invalid", invite);
    id = row.id;
  } catch (e) {
    console.error("[login] failed", (e as { code?: string })?.code ?? "unknown");
    return redirectWithError(LOGIN_PAGE, "server", invite);
  }
  return redirectWithSession(await landingAfterAuth(invite, id), createSession(id));
}

import { NextResponse } from "next/server";
import { LOGIN_PAGE, forbidden, isCrossSiteRequest, redirectClearingSession } from "@/lib/auth";

export async function POST(req: Request): Promise<NextResponse> {
  if (isCrossSiteRequest(req)) return forbidden();
  return redirectClearingSession(LOGIN_PAGE);
}

import { NextResponse } from "next/server";
import { currentUser, isCrossSiteRequest, forbidden } from "@/lib/auth";
import { createOrder } from "@/lib/orders";
import type { CartItem } from "@/lib/cart-context";

type OrderRequestBody = {
  fulfillment: "pickup" | "delivery";
  fulfillmentAt: string;
  contactName: string;
  contactPhone: string;
  address: string | null;
  notes: string | null;
  items: CartItem[];
};

export async function POST(req: Request): Promise<NextResponse> {
  if (isCrossSiteRequest(req)) return forbidden();
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  let body: OrderRequestBody;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "bad_request" }, { status: 400 });
  }

  if (
    !body ||
    (body.fulfillment !== "pickup" && body.fulfillment !== "delivery") ||
    !body.fulfillmentAt ||
    !body.contactName?.trim() ||
    !body.contactPhone?.trim() ||
    !Array.isArray(body.items) ||
    body.items.length === 0
  ) {
    return NextResponse.json({ error: "bad_request" }, { status: 400 });
  }
  if (body.fulfillment === "delivery" && !body.address?.trim()) {
    return NextResponse.json({ error: "bad_request" }, { status: 400 });
  }

  try {
    const orderId = await createOrder({
      customerId: user.id,
      fulfillment: body.fulfillment,
      fulfillmentAt: body.fulfillmentAt,
      contactName: body.contactName.trim().slice(0, 200),
      contactPhone: body.contactPhone.trim().slice(0, 40),
      address: body.fulfillment === "delivery" ? body.address!.trim().slice(0, 400) : null,
      notes: body.notes?.trim().slice(0, 1000) || null,
      items: body.items,
    });
    return NextResponse.json({ orderId });
  } catch (e) {
    console.error("[orders] create failed", (e as { code?: string })?.code ?? "unknown");
    return NextResponse.json({ error: "server" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import bcrypt from "bcryptjs";
import { query } from "@/lib/db";
import { createSession } from "@/lib/session";
import {
  BCRYPT_ROUNDS,
  LIMITS,
  SIGNUP_PAGE,
  clientIp,
  forbidden,
  isCrossSiteRequest,
  isValidEmail,
  landingAfterAuth,
  readCredentials,
  redirectWithError,
  redirectWithSession,
  tooManyAttempts,
} from "@/lib/auth";

export async function POST(req: Request): Promise<NextResponse> {
  if (isCrossSiteRequest(req)) return forbidden();
  const { email, password, invite, name } = await readCredentials(req);
  if (tooManyAttempts([{ key: `signup:ip:${clientIp(req)}`, limit: LIMITS.ip }])) {
    return redirectWithError(SIGNUP_PAGE, "too_many", invite);
  }
  if (!isValidEmail(email) || password.length < 8) {
    return redirectWithError(SIGNUP_PAGE, "bad_input", invite);
  }
  let id: number;
  try {
    const passwordHash = await bcrypt.hash(password, BCRYPT_ROUNDS);
    const inserted = await query<{ id: number }>(
      "INSERT INTO users (email, password_hash, name) VALUES ($1, $2, $3) RETURNING id",
      [email, passwordHash, name || null],
    );
    id = inserted.rows[0].id;
  } catch (e) {
    if ((e as { code?: string })?.code === "23505") return redirectWithError(SIGNUP_PAGE, "exists", invite);
    console.error("[signup] failed", (e as { code?: string })?.code ?? "unknown");
    return redirectWithError(SIGNUP_PAGE, "server", invite);
  }
  return redirectWithSession(await landingAfterAuth(invite, id), createSession(id));
}

import { notFound } from "next/navigation";
import { CakeVisual } from "@/app/components/CakeVisual";
import { CustomizePanel } from "@/app/components/CustomizePanel";
import { formatCents } from "@/lib/format";
import { getCakeBySlug } from "@/lib/cakes";

export default async function CakeDetailPage({ params }: { params: { slug: string } }) {
  const result = await getCakeBySlug(params.slug);
  if (!result) notFound();
  const { cake, options } = result;

  return (
    <main className="mx-auto max-w-5xl px-4 py-10 sm:px-6">
      <div className="grid gap-10 md:grid-cols-2">
        <CakeVisual name={cake.name} className="aspect-square w-full rounded-xl" />
        <div>
          <h1 className="font-display text-3xl font-semibold tracking-tight text-text">{cake.name}</h1>
          <p className="mt-2 break-words text-textMuted">{cake.description}</p>
          <p className="mt-3 text-xl font-semibold text-text">from {formatCents(cake.base_price_cents)}</p>
          {cake.dietary_tags.length > 0 && (
            <div className="mt-3 flex gap-2">
              {cake.dietary_tags.map((tag) => (
                <span key={tag} className="rounded-full bg-surface2 px-2.5 py-0.5 text-xs font-medium capitalize text-textMuted">
                  {tag}
                </span>
              ))}
            </div>
          )}
          <div className="mt-8">
            <CustomizePanel cake={cake} options={options} />
          </div>
        </div>
      </div>
    </main>
  );
}

