import { Cake as CakeIcon } from "lucide-react";

// Deterministic, always-renders product visual: a warm gradient tinted from the
// brand accent + a category icon + the cake's initial. Never a remote stock
// image URL (those 404/return the wrong subject) — this can never break.
export function CakeVisual({ name, className = "" }: { name: string; className?: string }) {
  return (
    <div
      className={`flex items-center justify-center bg-gradient-to-br from-accent/20 via-surface2 to-accent/10 ${className}`}
    >
      <div className="flex flex-col items-center gap-2 text-accent">
        <CakeIcon className="h-10 w-10" strokeWidth={1.5} />
        <span className="font-display text-2xl font-semibold">{name.charAt(0).toUpperCase()}</span>
      </div>
    </div>
  );
}

"use client";

