"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/app/components/ui/button";
import { formatCents } from "@/lib/format";
import { useCart } from "@/lib/cart-context";

const DELIVERY_FEE_CENTS = 1200;

export function CheckoutForm({ defaultName, defaultPhone }: { defaultName: string; defaultPhone: string }) {
  const router = useRouter();
  const { items, subtotalCents, clear } = useCart();
  const [fulfillment, setFulfillment] = useState<"pickup" | "delivery">("pickup");
  const [contactName, setContactName] = useState(defaultName);
  const [contactPhone, setContactPhone] = useState(defaultPhone);
  const [address, setAddress] = useState("");
  const [date, setDate] = useState("");
  const [notes, setNotes] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const deliveryFee = fulfillment === "delivery" ? DELIVERY_FEE_CENTS : 0;
  const total = subtotalCents + deliveryFee;

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    if (!date) {
      setError("Choose a pickup or delivery date.");
      return;
    }
    if (fulfillment === "delivery" && !address.trim()) {
      setError("Enter a delivery address.");
      return;
    }
    setSubmitting(true);
    try {
      const res = await fetch("/api/orders", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          fulfillment,
          fulfillmentAt: new Date(date).toISOString(),
          contactName,
          contactPhone,
          address: fulfillment === "delivery" ? address : null,
          notes,
          items,
        }),
      });
      if (!res.ok) {
        setError("Something went wrong placing your order. Try again.");
        setSubmitting(false);
        return;
      }
      const data = await res.json();
      clear();
      router.push(`/orders/${data.orderId}`);
    } catch {
      setError("Something went wrong placing your order. Try again.");
      setSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="flex flex-col gap-5">
      <div className="flex gap-2">
        {(["pickup", "delivery"] as const).map((option) => (
          <button
            key={option}
            type="button"
            onClick={() => setFulfillment(option)}
            className={`flex-1 rounded-lg border px-4 py-2.5 text-sm font-medium capitalize transition ${
              fulfillment === option
                ? "border-accent bg-accent text-accentFg"
                : "border-border bg-surface text-text hover:bg-surface2"
            }`}
          >
            {option}
          </button>
        ))}
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
          Name
          <input
            required
            value={contactName}
            onChange={(e) => setContactName(e.target.value)}
            className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
          />
        </label>
        <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
          Phone
          <input
            required
            value={contactPhone}
            onChange={(e) => setContactPhone(e.target.value)}
            className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
          />
        </label>
      </div>

      {fulfillment === "delivery" && (
        <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
          Delivery address
          <input
            required
            value={address}
            onChange={(e) => setAddress(e.target.value)}
            className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
          />
        </label>
      )}

      <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
        {fulfillment === "pickup" ? "Pickup date & time" : "Delivery date & time"}
        <input
          required
          type="datetime-local"
          value={date}
          onChange={(e) => setDate(e.target.value)}
          className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
        />
      </label>

      <label className="flex flex-col gap-1.5 text-sm font-medium text-text">
        Order notes (optional)
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          rows={3}
          className="rounded-lg border border-border bg-surface px-3 py-2 text-sm outline-none focus:border-accent"
        />
      </label>

      {error && <p className="text-sm text-red-600">{error}</p>}

      <div className="rounded-xl border border-border bg-surface2/60 p-4">
        <div className="flex justify-between text-sm text-textMuted">
          <span>Subtotal</span>
          <span>{formatCents(subtotalCents)}</span>
        </div>
        <div className="flex justify-between text-sm text-textMuted">
          <span>Delivery fee</span>
          <span>{deliveryFee > 0 ? formatCents(deliveryFee) : "—"}</span>
        </div>
        <div className="mt-2 flex justify-between border-t border-border pt-2 font-semibold text-text">
          <span>Total</span>
          <span>{formatCents(total)}</span>
        </div>
      </div>

      <Button type="submit" size="lg" disabled={submitting}>
        {submitting ? "Placing order…" : "Place order"}
      </Button>
      <p className="text-center text-xs text-textMuted">
        Payment is collected in person for v1 — online payment is coming soon.
      </p>
    </form>
  );
}

"use client";

import { useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/app/components/ui/button";
import { formatCents } from "@/lib/format";
import { useCart } from "@/lib/cart-context";
import type { Cake, CakeOption } from "@/lib/cakes";

const KIND_LABELS: Record<string, string> = {
  size: "Size",
  flavor: "Flavor",
  filling: "Filling",
  frosting: "Frosting",
};
const KIND_ORDER = ["size", "flavor", "filling", "frosting"];

export function CustomizePanel({ cake, options }: { cake: Cake; options: CakeOption[] }) {
  const router = useRouter();
  const { addItem } = useCart();

  const grouped = useMemo(() => {
    const byKind = new Map<string, CakeOption[]>();
    for (const opt of options) {
      const list = byKind.get(opt.kind) ?? [];
      list.push(opt);
      byKind.set(opt.kind, list);
    }
    return KIND_ORDER.filter((k) => byKind.has(k)).map((kind) => ({ kind, options: byKind.get(kind)! }));
  }, [options]);

  const [selected, setSelected] = useState<Record<string, CakeOption>>(() => {
    const initial: Record<string, CakeOption> = {};
    for (const group of grouped) initial[group.kind] = group.options[0];
    return initial;
  });
  const [quantity, setQuantity] = useState(1);
  const [message, setMessage] = useState("");
  const [added, setAdded] = useState(false);

  const unitPriceCents =
    cake.base_price_cents + Object.values(selected).reduce((sum, o) => sum + o.price_delta_cents, 0);
  const totalCents = unitPriceCents * quantity;

  function handleAddToCart() {
    addItem({
      cakeId: cake.id,
      slug: cake.slug,
      name: cake.name,
      photoUrl: cake.photo_url,
      basePriceCents: cake.base_price_cents,
      quantity,
      selectedOptions: Object.values(selected).map((o) => ({
        kind: o.kind,
        label: o.label,
        priceDeltaCents: o.price_delta_cents,
      })),
      messageOnCake: message,
    });
    setAdded(true);
    setTimeout(() => router.push("/cart"), 500);
  }

  return (
    <div className="flex flex-col gap-6">
      {grouped.map((group) => (
        <div key={group.kind}>
          <p className="mb-2 text-sm font-semibold text-text">{KIND_LABELS[group.kind] ?? group.kind}</p>
          <div className="flex flex-wrap gap-2">
            {group.options.map((option) => (
              <button
                key={option.id}
                type="button"
                onClick={() => setSelected((prev) => ({ ...prev, [group.kind]: option }))}
                className={`rounded-full border px-3.5 py-1.5 text-sm font-medium transition ${
                  selected[group.kind]?.id === option.id
                    ? "border-accent bg-accent text-accentFg"
                    : "border-border bg-surface text-text hover:bg-surface2"
                }`}
              >
                {option.label}
                {option.price_delta_cents > 0 && ` (+${formatCents(option.price_delta_cents)})`}
              </button>
            ))}
          </div>
        </div>
      ))}

      <div>
        <label htmlFor="message-on-cake" className="mb-2 block text-sm font-semibold text-text">
          Message on top (optional)
        </label>
        <input
          id="message-on-cake"
          type="text"
          maxLength={60}
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          placeholder="Happy Birthday, Sam!"
          className="w-full rounded-lg border border-border bg-surface px-3 py-2 text-sm text-text outline-none focus:border-accent"
        />
      </div>

      <div className="flex items-center gap-3">
        <span className="text-sm font-semibold text-text">Quantity</span>
        <div className="flex items-center rounded-lg border border-border">
