// Shared helpers for the signup/login/logout routes and page-level auth guards.
import "server-only";
import { createHash } from "node:crypto";
import { cookies } from "next/headers";
import { notFound, redirect as goTo } from "next/navigation";
import { NextResponse } from "next/server";
import bcrypt from "bcryptjs";
import { query, withTransaction } from "@/lib/db";
import { readSession } from "@/lib/session";

export const AFTER_LOGIN = "/account/orders";
export const LOGIN_PAGE = "/signin";
export const SIGNUP_PAGE = "/signin";

const COOKIE = "session";
const COOKIE_ATTRS = "Path=/; HttpOnly; Secure; SameSite=Lax";
const MAX_AGE_S = 60 * 60 * 24 * 7;
export const BCRYPT_ROUNDS = 12;

/** 303 with a RELATIVE Location — the browser resolves it against the public
 *  origin it actually loaded (req.url reflects the internal bind, not the
 *  public host, so an absolute redirect would send users to a dead page). */
export function redirect(path: string): NextResponse {
  return new NextResponse(null, { status: 303, headers: { Location: path } });
}

const ERRORS = {
  too_many: "Too many attempts. Wait a few minutes and try again.",
  bad_input: "Enter a valid email and a password of at least 8 characters.",
  exists: "Couldn't create that account. If you already have one, sign in.",
  invalid: "Invalid email or password.",
  server: "Something went wrong. Try again.",
  invite: "This invite link has expired or was already used. Ask the site owner for a new one.",
} as const;
export type AuthError = keyof typeof ERRORS;

export function authErrorMessage(code: string | undefined): string | null {
  return typeof code === "string" && Object.prototype.hasOwnProperty.call(ERRORS, code)
    ? ERRORS[code as AuthError]
    : null;
}

export function redirectWithError(page: string, code: AuthError, invite = ""): NextResponse {
  const q = new URLSearchParams({ error: code });
  if (isInviteToken(invite)) q.set("invite", invite);
  return redirect(`${page}?${q}`);
}

export function redirectWithSession(path: string, token: string): NextResponse {
  const res = redirect(path);
  res.headers.append("Set-Cookie", `${COOKIE}=${token}; ${COOKIE_ATTRS}; Max-Age=${MAX_AGE_S}`);
  return res;
}

export function redirectClearingSession(path: string): NextResponse {
  const res = redirect(path);
  res.headers.append("Set-Cookie", `${COOKIE}=; ${COOKIE_ATTRS}; Max-Age=0`);
  return res;
}

/** Email/password/name/invite from a form POST. `name` is only used by signup;
 *  login simply ignores it. Never throws. */
export async function readCredentials(
  req: Request,
): Promise<{ email: string; password: string; invite: string; name: string }> {
  try {
    const form = await req.formData();
    return {
      email: String(form.get("email") ?? "").trim().toLowerCase().slice(0, 254),
      password: String(form.get("password") ?? "").slice(0, 200),
      invite: String(form.get("invite") ?? "").slice(0, 200),
      name: String(form.get("name") ?? "").trim().slice(0, 200),
    };
  } catch {
    return { email: "", password: "", invite: "", name: "" };
  }
}

export function isValidEmail(email: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

export function clientIp(req: Request): string {
  const hops = (req.headers.get("x-forwarded-for") ?? "").split(",").map((h) => h.trim()).filter(Boolean);
  return hops[hops.length - 1] || req.headers.get("x-real-ip")?.trim() || "unknown";
}

export function isCrossSiteRequest(req: Request): boolean {
  if (req.headers.get("sec-fetch-site") === "cross-site") return true;
  const origin = req.headers.get("origin");
  if (!origin) return false;
  const host = (req.headers.get("x-forwarded-host") ?? req.headers.get("host") ?? "").split(",")[0].trim();
  try {
    return new URL(origin).host !== host;
  } catch {
    return true;
  }
}

export function forbidden(): NextResponse {
  return new NextResponse("Forbidden", { status: 403 });
}

const WINDOW_MS = 15 * 60 * 1000;
export const LIMITS = { ip: 30, email: 10 } as const;
const MAX_KEYS = 10_000;
const attempts = new Map<string, number[]>();

export function tooManyAttempts(keys: Array<{ key: string; limit: number }>, now = Date.now()): boolean {
  let blocked = false;
  for (const { key, limit } of keys) {
    const recent = (attempts.get(key) ?? []).filter((t) => now - t < WINDOW_MS);
    recent.push(now);
    attempts.delete(key);
    attempts.set(key, recent);
    if (recent.length > limit) blocked = true;
  }
  while (attempts.size > MAX_KEYS) {
    const oldest = attempts.keys().next().value;
    if (oldest === undefined) break;
    attempts.delete(oldest);
  }
  return blocked;
}

let dummyHash: string | null = null;
export async function verifyPassword(password: string, hash: string | null): Promise<boolean> {
  if (hash) return bcrypt.compare(password, hash);
  dummyHash ??= await bcrypt.hash("not-a-real-password", BCRYPT_ROUNDS);
  await bcrypt.compare(password, dummyHash);
  return false;
}

export type Role = "user" | "admin";
export type SiteUser = { id: number; email: string; role: Role; name: string | null };

export async function currentUser(): Promise<SiteUser | null> {
  const sess = readSession(cookies().get(COOKIE)?.value);
  if (!sess) return null;
  const r = await query<SiteUser>("SELECT id, email, role, name FROM users WHERE id = $1", [sess.uid]);
  return r.rows[0] ?? null;
}

export async function requireAdminPage(): Promise<SiteUser> {
  const user = await currentUser();
  if (!user) goTo(LOGIN_PAGE);
  if (user.role !== "admin") notFound();
  return user;
}

export async function requireAdminRoute(): Promise<
  { user: SiteUser; error: null } | { user: null; error: NextResponse }
> {
  const user = await currentUser();
  if (!user) return { user: null, error: new NextResponse("Unauthorized", { status: 401 }) };
  if (user.role !== "admin") return { user: null, error: forbidden() };
  return { user, error: null };
}

export async function requireAdminAction(): Promise<SiteUser> {
  const user = await currentUser();
  if (user?.role !== "admin") throw new Error("Forbidden");
  return user;
}

const INVITE_TOKEN = /^[A-Za-z0-9_-]{20,128}$/;
export function isInviteToken(t: string | undefined): t is string {
  return typeof t === "string" && INVITE_TOKEN.test(t);
}

export async function redeemInvite(token: string, userId: number): Promise<Role | null> {
  if (!isInviteToken(token)) return null;
  const hash = createHash("sha256").update(token).digest("hex");
  return withTransaction(async (c) => {
    const inv = await c.query<{ role: Role }>(
      "UPDATE invites SET used_at = now(), used_by = $2 WHERE token_hash = $1 AND used_at IS NULL AND revoked_at IS NULL AND expires_at > now() RETURNING role",
      [hash, userId],
    );
    const role = inv.rows[0]?.role;
    if (!role) return null;
    await c.query("UPDATE users SET role = $1 WHERE id = $2 AND role = 'user'", [role, userId]);
    await c.query(
      "INSERT INTO _zavi_audit (event, target_user_id, detail) VALUES ('invite_redeemed', $1, $2)",
      [userId, JSON.stringify({ role })],
    );
    return role;
  });
}

export async function landingAfterAuth(invite: string, userId: number): Promise<string> {
  if (!invite) return AFTER_LOGIN;
  try {
    if (await redeemInvite(invite, userId)) return AFTER_LOGIN;
  } catch (e) {
    console.error("[invite] redeem failed", (e as { code?: string })?.code ?? "unknown");
  }
  return `${AFTER_LOGIN}?error=invite`;
}

import "server-only";
import { query, hasDatabase } from "@/lib/db";

export type CakeOption = {
  id: number;
  kind: "size" | "flavor" | "filling" | "frosting";
  label: string;
  price_delta_cents: number;
};

export type Cake = {
  id: number;
  slug: string;
  name: string;
  description: string;
  base_price_cents: number;
  occasion_tags: string[];
  dietary_tags: string[];
  photo_url: string | null;
  active: boolean;
  is_sample: boolean;
};

export async function listActiveCakes(occasion?: string): Promise<Cake[]> {
  if (!hasDatabase()) return [];
  if (occasion) {
    const r = await query<Cake>(
      "SELECT * FROM cakes WHERE active = true AND $1 = ANY(occasion_tags) ORDER BY created_at DESC",
      [occasion],
    );
    return r.rows;
  }
  const r = await query<Cake>("SELECT * FROM cakes WHERE active = true ORDER BY created_at DESC");
  return r.rows;
}

export async function getCakeBySlug(slug: string): Promise<{ cake: Cake; options: CakeOption[] } | null> {
  if (!hasDatabase()) return null;
  const cakeResult = await query<Cake>("SELECT * FROM cakes WHERE slug = $1 AND active = true", [slug]);
  const cake = cakeResult.rows[0];
  if (!cake) return null;
  const optionsResult = await query<CakeOption>(
    "SELECT id, kind, label, price_delta_cents FROM cake_options WHERE cake_id = $1 ORDER BY kind, sort_order",
    [cake.id],
  );
  return { cake, options: optionsResult.rows };
}

export async function listAllCakesForAdmin(): Promise<Cake[]> {
  if (!hasDatabase()) return [];
  const r = await query<Cake>("SELECT * FROM cakes ORDER BY created_at DESC");
  return r.rows;
}

export async function hasSampleCakes(): Promise<boolean> {
  if (!hasDatabase()) return false;
  const r = await query<{ exists: boolean }>("SELECT EXISTS(SELECT 1 FROM cakes WHERE is_sample = true) AS exists");
  return r.rows[0]?.exists ?? false;
}

"use client";

// Client-side cart. Persisted to localStorage — this is ephemeral UI state
// (not an order of record), so no server round-trip is needed until checkout,
// where the whole cart is submitted to POST /api/orders in one request.
import { createContext, useContext, useEffect, useMemo, useState, type ReactNode } from "react";

export type CartOption = { kind: string; label: string; priceDeltaCents: number };

export type CartItem = {
  cakeId: number;
  slug: string;
  name: string;
  photoUrl: string | null;
  basePriceCents: number;
  quantity: number;
  selectedOptions: CartOption[];
  messageOnCake: string;
};

type CartContextValue = {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (index: number) => void;
  setQuantity: (index: number, quantity: number) => void;
  clear: () => void;
  itemPriceCents: (item: CartItem) => number;
  subtotalCents: number;
  count: number;
};

const CartContext = createContext<CartContextValue | null>(null);
const STORAGE_KEY = "cake-co-cart";

function itemPriceCents(item: CartItem): number {
  const optionsDelta = item.selectedOptions.reduce((sum, o) => sum + o.priceDeltaCents, 0);
  return (item.basePriceCents + optionsDelta) * item.quantity;
}

export function CartProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<CartItem[]>([]);
  const [hydrated, setHydrated] = useState(false);

  useEffect(() => {
    try {
      const raw = window.localStorage.getItem(STORAGE_KEY);
      if (raw) setItems(JSON.parse(raw));
    } catch {
      // ignore malformed/absent storage
    }
    setHydrated(true);
  }, []);

  useEffect(() => {
    if (!hydrated) return;
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items, hydrated]);

  const value = useMemo<CartContextValue>(() => {
    const subtotalCents = items.reduce((sum, item) => sum + itemPriceCents(item), 0);
    return {
      items,
      addItem: (item) => setItems((prev) => [...prev, item]),
      removeItem: (index) => setItems((prev) => prev.filter((_, i) => i !== index)),
      setQuantity: (index, quantity) =>
        setItems((prev) => prev.map((it, i) => (i === index ? { ...it, quantity: Math.max(1, quantity) } : it))),
      clear: () => setItems([]),
      itemPriceCents,
      subtotalCents,
      count: items.reduce((sum, item) => sum + item.quantity, 0),
    };
  }, [items]);

  return <CartContext.Provider value={value}>{children}</CartContext.Provider>;
}

export function useCart(): CartContextValue {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error("useCart must be used within CartProvider");
  return ctx;
}

// Server-only Postgres client. DATABASE_URL is server-only (never NEXT_PUBLIC_,
// never logged, never sent to the browser). Registers an int8 type-parser so
// BIGINT/BIGSERIAL ids deserialize as JS numbers everywhere (node-postgres
// otherwise returns them as strings, which breaks session-uid comparisons).
import "server-only";
import pg from "pg";

pg.types.setTypeParser(20, (v: string | null) => (v === null ? null : Number(v)));

let _pool: pg.Pool | null = null;

/** True when a DATABASE_URL is present — guard DB reads so pages can render an
 *  empty/error state instead of crashing before the resource is provisioned. */
export function hasDatabase(): boolean {
  return Boolean(process.env.DATABASE_URL);
}

function pool(): pg.Pool {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error("DATABASE_URL is not set — refusing to query without a database");
  }
  if (!_pool) {
    _pool = new pg.Pool({ connectionString: url });
  }
  return _pool;
}

/** Parameterized query. ALWAYS use $1, $2, … placeholders — never string
 *  interpolation. Server components / route handlers / server actions only. */
export async function query<T extends pg.QueryResultRow = pg.QueryResultRow>(
  text: string,
  params: unknown[] = [],
): Promise<pg.QueryResult<T>> {
  return pool().query<T>(text, params as never);
}

/** Run fn inside one transaction (BEGIN/COMMIT, ROLLBACK on throw). */
export async function withTransaction<T>(fn: (client: pg.PoolClient) => Promise<T>): Promise<T> {
  const client = await pool().connect();
  try {
    await client.query("BEGIN");
    const out = await fn(client);
    await client.query("COMMIT");
    return out;
  } catch (e) {
    await client.query("ROLLBACK").catch(() => undefined);
    throw e;
  } finally {
    client.release();
  }
}

export function formatCents(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

export function formatDateTime(iso: string): string {
  return new Date(iso).toLocaleString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

