import "server-only";
import { query, withTransaction, hasDatabase } from "@/lib/db";
import type { CartItem } from "@/lib/cart-context";

export type OrderStatus =
  | "pending"
  | "paid"
  | "in_kitchen"
  | "ready"
  | "out_for_delivery"
  | "completed"
  | "cancelled";

export type Order = {
  id: number;
  customer_id: number;
  status: OrderStatus;
  fulfillment: "pickup" | "delivery";
  fulfillment_at: string;
  contact_name: string;
  contact_phone: string;
  address: string | null;
  subtotal_cents: number;
  delivery_fee_cents: number;
  total_cents: number;
  notes: string | null;
  created_at: string;
};

export type OrderItem = {
  id: number;
  order_id: number;
  cake_id: number;
  quantity: number;
  unit_price_cents: number;
  selected_options: { kind: string; label: string; priceDeltaCents: number }[];
  message_on_cake: string | null;
  cake_name?: string;
};

const DELIVERY_FEE_CENTS = 1200;

export async function createOrder(params: {
  customerId: number;
  fulfillment: "pickup" | "delivery";
  fulfillmentAt: string;
  contactName: string;
  contactPhone: string;
  address: string | null;
  notes: string | null;
  items: CartItem[];
}): Promise<number> {
  const deliveryFee = params.fulfillment === "delivery" ? DELIVERY_FEE_CENTS : 0;
  const subtotal = params.items.reduce((sum, item) => {
    const optionsDelta = item.selectedOptions.reduce((s, o) => s + o.priceDeltaCents, 0);
    return sum + (item.basePriceCents + optionsDelta) * item.quantity;
  }, 0);
  const total = subtotal + deliveryFee;

  return withTransaction(async (c) => {
    const orderResult = await c.query<{ id: number }>(
      `INSERT INTO orders
         (customer_id, status, fulfillment, fulfillment_at, contact_name, contact_phone, address, subtotal_cents, delivery_fee_cents, total_cents, notes)
       VALUES ($1, 'pending', $2, $3, $4, $5, $6, $7, $8, $9, $10)
       RETURNING id`,
      [
        params.customerId,
        params.fulfillment,
        params.fulfillmentAt,
        params.contactName,
        params.contactPhone,
        params.address,
        subtotal,
        deliveryFee,
        total,
        params.notes,
      ],
    );
    const orderId = orderResult.rows[0].id;
    for (const item of params.items) {
      const unitPrice = item.basePriceCents + item.selectedOptions.reduce((s, o) => s + o.priceDeltaCents, 0);
      await c.query(
        `INSERT INTO order_items (order_id, cake_id, quantity, unit_price_cents, selected_options, message_on_cake)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [orderId, item.cakeId, item.quantity, unitPrice, JSON.stringify(item.selectedOptions), item.messageOnCake || null],
      );
    }
    await c.query("INSERT INTO events (order_id, from_status, to_status) VALUES ($1, NULL, 'pending')", [orderId]);
    return orderId;
  });
}

export async function getOrderForCustomer(orderId: number, customerId: number): Promise<Order | null> {
  if (!hasDatabase()) return null;
  const r = await query<Order>("SELECT * FROM orders WHERE id = $1 AND customer_id = $2", [orderId, customerId]);
  return r.rows[0] ?? null;
}

export async function getOrderAsAdmin(orderId: number): Promise<Order | null> {
  if (!hasDatabase()) return null;
  const r = await query<Order>("SELECT * FROM orders WHERE id = $1", [orderId]);
  return r.rows[0] ?? null;
}

export async function listOrderItems(orderId: number): Promise<OrderItem[]> {
  if (!hasDatabase()) return [];
  const r = await query<OrderItem>(
    `SELECT oi.*, c.name AS cake_name
     FROM order_items oi
     JOIN cakes c ON c.id = oi.cake_id
     WHERE oi.order_id = $1`,
    [orderId],
  );
  return r.rows;
}

export async function listOrdersForCustomer(customerId: number): Promise<Order[]> {
  if (!hasDatabase()) return [];
  const r = await query<Order>("SELECT * FROM orders WHERE customer_id = $1 ORDER BY created_at DESC", [customerId]);
  return r.rows;
}

export async function listAllOrders(): Promise<Order[]> {
  if (!hasDatabase()) return [];
  const r = await query<Order>("SELECT * FROM orders ORDER BY created_at DESC LIMIT 200");
  return r.rows;
}

export async function updateOrderStatus(orderId: number, toStatus: OrderStatus): Promise<void> {
  await withTransaction(async (c) => {
    const current = await c.query<{ status: OrderStatus }>("SELECT status FROM orders WHERE id = $1", [orderId]);
    const fromStatus = current.rows[0]?.status ?? null;
    await c.query("UPDATE orders SET status = $1 WHERE id = $2", [toStatus, orderId]);
    await c.query("INSERT INTO events (order_id, from_status, to_status) VALUES ($1, $2, $3)", [
      orderId,
      fromStatus,
      toStatus,
    ]);
  });
}

// Signed, expiring session token. SESSION_SECRET is provisioned server-only by
// the platform. NO hardcoded fallback — a missing secret fails closed instead of
// signing with a guessable default (that would let anyone forge a login cookie).
import "server-only";
import { createHmac, timingSafeEqual } from "node:crypto";

function sessionSecret(): string {
  const s = process.env.SESSION_SECRET;
  if (!s || s.length < 16) {
    throw new Error("SESSION_SECRET is not set — refusing to sign/verify with a guessable key");
  }
  return s;
}

const MAX_AGE_S = 60 * 60 * 24 * 7; // 7 days

function sign(payloadB64: string): string {
  return createHmac("sha256", sessionSecret()).update(payloadB64).digest("base64url");
}

/** Canonical uid type = NUMBER end-to-end (pg BIGINT ids arrive as strings from
 *  node-postgres without the int8 type-parser registered in lib/db.ts). */
export function createSession(uid: number | string): string {
  const payload = { uid: Number(uid), exp: Math.floor(Date.now() / 1000) + MAX_AGE_S };
  const b64 = Buffer.from(JSON.stringify(payload)).toString("base64url");
  return `${b64}.${sign(b64)}`;
}

export function readSession(token: string | undefined): { uid: number } | null {
  if (!token) return null;
  const [b64, mac] = token.split(".");
  if (!b64 || !mac) return null;
  const expected = sign(b64);
  const a = Buffer.from(mac);
  const b = Buffer.from(expected);
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  const { uid, exp } = JSON.parse(Buffer.from(b64, "base64url").toString());
  if (!exp || exp < Math.floor(Date.now() / 1000)) return null;
  const id = Number(uid);
  if (!Number.isInteger(id)) return null;
  return { uid: id };
}

